import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十二卦 艮 艮为山 艮上艮下","description":"周易 - 第五十二卦 艮 艮为山 艮上艮下","frontmatter":{"title":"第五十二卦 艮 艮为山 艮上艮下","description":"周易 - 第五十二卦 艮 艮为山 艮上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/053.md","filePath":"zh/classics/zhouyi/053.md"}'),l={name:"zh/classics/zhouyi/053.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="艮" tabindex="-1">艮 <a class="header-anchor" href="#艮" aria-label="Permalink to “艮”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>艮其背，不获其身，行其庭，不见其人，无咎。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以不获其身，行其庭不见其人，无咎也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>兼山，艮；君子以思不出其位。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>艮其趾，无咎，利永贞。象曰：艮其趾， 未失正也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>艮其腓，不拯其随，其心不快。象曰：不拯其随，未退听也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>艮其限，列其夤，厉薰心。象曰：艮其限，危薰心也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>艮其身，无咎。象曰：艮其身，止诸躬也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>艮其辅，言有序，悔亡。象曰：艮其辅，以中正也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>敦艮，吉。象曰：敦艮之吉，以厚终也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
